import React from 'react';
import { MarketInsight, AssetStatus, CompletionStatus } from '../types';
import { Edit2, Trash2, Calendar, TrendingUp, TrendingDown, Activity, Target, ChevronRight, CheckCircle2, XCircle, Clock } from 'lucide-react';

interface MarketCardProps {
  insight: MarketInsight;
  onEdit: (insight: MarketInsight) => void;
  onDelete: (id: string) => void;
  onToggleCompletion: (id: string) => void;
}

const getAssetStatusStyle = (status: AssetStatus) => {
  switch (status) {
    case '看涨': return {
      color: 'text-red-500',
      bg: 'bg-red-50',
      border: 'border-red-100',
      icon: <TrendingUp className="w-4 h-4" />
    };
    case '看跌': return {
      color: 'text-emerald-500',
      bg: 'bg-emerald-50',
      border: 'border-emerald-100',
      icon: <TrendingDown className="w-4 h-4" />
    };
    default: return {
      color: 'text-blue-500',
      bg: 'bg-blue-50',
      border: 'border-blue-100',
      icon: <Activity className="w-4 h-4" />
    };
  }
};

const getCompletionStatusStyle = (status: CompletionStatus) => {
  switch (status) {
    case '已完成': return {
      label: '已完成',
      color: 'text-emerald-600',
      bg: 'bg-emerald-50',
      icon: <CheckCircle2 className="w-3 h-3" />
    };
    case '已失效': return {
      label: '已失效',
      color: 'text-slate-500',
      bg: 'bg-slate-50',
      icon: <XCircle className="w-3 h-3" />
    };
    default: return {
      label: '进行中',
      color: 'text-red-600',
      bg: 'bg-red-50',
      icon: <Clock className="w-3 h-3" />
    };
  }
};

const MarketCard: React.FC<MarketCardProps> = ({ insight, onEdit, onDelete, onToggleCompletion }) => {
  const date = new Date(insight.updatedAt).toLocaleDateString('zh-CN', {
    month: 'short',
    day: 'numeric'
  });

  const assetStyle = getAssetStatusStyle(insight.status);
  const completionStyle = getCompletionStatusStyle(insight.completionStatus);
  const isArchived = insight.completionStatus !== '进行中';

  return (
    <div className={`group relative bg-white border border-gray-100 rounded-[2.5rem] p-8 transition-all duration-500 hover:shadow-[0_30px_60px_-15px_rgba(0,0,0,0.08)] flex flex-col min-h-[420px] ${isArchived ? 'opacity-70 hover:opacity-100' : ''}`}>

      {/* 顶部标识 */}
      <div className="flex justify-between items-start mb-8">
        <div>
          <div className="flex items-center gap-2 mb-1">
             <h3 className="text-3xl font-black text-[#12141c] tracking-tighter">{insight.symbol}</h3>
             <span className={`px-2 py-0.5 rounded-md text-[10px] font-black uppercase tracking-wider ${assetStyle.bg} ${assetStyle.color}`}>
                {insight.status}
             </span>
          </div>
          <div className="flex items-center text-[12px] text-gray-400 font-bold gap-2">
            <Calendar className="w-3.5 h-3.5" />
            {date}
          </div>
        </div>

        <button 
          onClick={() => onToggleCompletion(insight.id)}
          className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[10px] font-black border transition-all hover:scale-105 active:scale-95 ${completionStyle.bg} ${completionStyle.color} border-current/10`}
        >
          {completionStyle.icon}
          {completionStyle.label}
        </button>
      </div>

      {/* 内容主体 */}
      <div className="flex-grow space-y-6">
        <div>
          <p className="text-[11px] font-black text-gray-300 uppercase tracking-widest mb-2">核心观察</p>
          <p className="text-[15px] font-medium leading-relaxed text-gray-700">
            {insight.focusPoints}
          </p>
        </div>

        {insight.entryLevel && (
          <div className="flex items-center gap-3 text-gray-900">
            <Target className="w-4 h-4 text-gray-400" />
            <span className="text-[14px] font-black">点位: {insight.entryLevel}</span>
          </div>
