        <div className="pt-4 border-t border-gray-50">
          <p className="text-[11px] font-black text-gray-300 uppercase tracking-widest mb-2">应对策略</p>
          <div className="flex items-start gap-3">
             <ChevronRight className={`w-4 h-4 mt-0.5 ${assetStyle.color}`} />
             <p className="text-[15px] font-bold text-[#12141c] leading-snug">
               {insight.strategy}
             </p>
          </div>
        </div>
      </div>

      {/* 底部工具 */}
      <div className="mt-8 pt-6 border-t border-gray-50 flex justify-between items-center opacity-0 group-hover:opacity-100 transition-all duration-300">
