import { MarketInsight, Category, CompletionStatus, SortMode } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import { Plus, LayoutGrid, ListFilter, CalendarDays, Archive, Search, X } from 'lucide-react';

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>(() => {
    const saved = localStorage.getItem('trading_journal_v4');
    return saved ? JSON.parse(saved) : INITIAL_INSIGHTS;
  });

  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [sortMode, setSortMode] = useState<SortMode>('category');
  const [showForm, setShowForm] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    localStorage.setItem('trading_journal_v4', JSON.stringify(insights));
  }, [insights]);

  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    let result = insights;

    // 搜索过滤
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      result = result.filter(i => 
        i.symbol.toLowerCase().includes(query) || 
        i.focusPoints.toLowerCase().includes(query) || 
        i.strategy.toLowerCase().includes(query)
      );
    }

    // 分类过滤
    if (activeCategory !== '全部') {
      result = result.filter(i => i.category === activeCategory);
    }

    // 时间归档过滤
    if (selectedMonth) {
      result = result.filter(i => {
        const date = new Date(i.updatedAt);
        return `${date.getFullYear()}年${date.getMonth() + 1}月` === selectedMonth;
      });
    }
    return result;
  }, [insights, activeCategory, selectedMonth, searchQuery]);

  const { activeItems, archivedItems } = useMemo(() => {
    return {
      activeItems: filteredInsights.filter(i => i.completionStatus === '进行中'),
      archivedItems: filteredInsights.filter(i => i.completionStatus !== '进行中')
    };
  }, [filteredInsights]);

  const groupedActiveInsights = useMemo(() => {
    const groups: { [label: string]: MarketInsight[] } = {};
    activeItems.forEach(insight => {
      let label = sortMode === 'timeline' 
        ? new Date(insight.updatedAt).toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' })
        : insight.category;
      if (!groups[label]) groups[label] = [];
      groups[label].push(insight);
    });
    const entries = Object.entries(groups);
    return sortMode === 'category' 
      ? entries.sort((a, b) => CATEGORIES.indexOf(a[0] as any) - CATEGORIES.indexOf(b[0] as any))
      : entries.sort((a, b) => b[1][0].updatedAt - a[1][0].updatedAt);
  }, [activeItems, sortMode]);

  const handleSaveInsight = (data: Partial<MarketInsight>) => {
    if (editingInsight) {
      setInsights(prev => prev.map(i => i.id === editingInsight.id ? { ...i, ...data, updatedAt: data.updatedAt || i.updatedAt } as MarketInsight : i));
    } else {
      const newInsight: MarketInsight = {
        id: Math.random().toString(36).substr(2, 9),
        ...data as any,
        updatedAt: data.updatedAt || Date.now(),
        completionStatus: data.completionStatus || '进行中',
      };
      setInsights(prev => [newInsight, ...prev]);
    }
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = (id: string) => {
    if (window.confirm('确定要删除这条市场记录吗？')) {
      setInsights(prev => prev.filter(i => i.id !== id));
    }
  };

  const handleToggleCompletionStatus = (id: string) => {
    const statuses: CompletionStatus[] = ['进行中', '已完成', '已失效'];
    setInsights(prev => prev.map(i => {
      if (i.id === id) {
        const currentIndex = statuses.indexOf(i.completionStatus);
        const nextStatus = statuses[(currentIndex + 1) % statuses.length];
        return { ...i, completionStatus: nextStatus, updatedAt: Date.now() };
      }
      return i;
    }));
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-amber-100">
      {/* 极简顶栏 */}
      <header className="sticky top-0 z-[100] bg-white/80 backdrop-blur-xl border-b border-gray-100 px-8 h-[72px]">
        <div className="max-w-[1600px] mx-auto flex items-center justify-between h-full gap-8">
          <div className="flex items-center gap-3 shrink-0">
            <div className="bg-[#12141c] w-8 h-8 rounded-lg flex items-center justify-center">
              <LayoutGrid className="w-4 h-4 text-white" />
            </div>
            <h1 className="text-lg font-black text-[#12141c] tracking-tighter hidden sm:block">市场周刊</h1>
          </div>

          <div className="flex-grow flex items-center gap-4 max-w-3xl">
            {/* 搜索框 */}
            <div className="relative group flex-grow">
              <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                <Search className={`w-4 h-4 transition-colors ${searchQuery ? 'text-gray-900' : 'text-gray-300'}`} />
              </div>
              <input
                type="text"
                className="w-full bg-gray-100/50 border border-transparent focus:bg-white focus:border-gray-200 py-2.5 pl-10 pr-10 rounded-2xl text-[13px] font-bold outline-none transition-all placeholder:text-gray-300"
                placeholder="搜索资产代码、观察或策略..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
              {searchQuery && (
                <button 
                  onClick={() => setSearchQuery('')}
                  className="absolute inset-y-0 right-0 pr-3 flex items-center text-gray-300 hover:text-gray-900 transition-colors"
                >
                  <X className="w-4 h-4" />
                </button>
              )}
            </div>

            <nav className="hidden xl:flex items-center gap-1 bg-gray-100/50 p-1 rounded-2xl shrink-0">
              {CATEGORIES.map(cat => (
                <button
                  key={cat}
                  onClick={() => setActiveCategory(cat)}
                  className={`px-5 py-2 rounded-xl text-[13px] font-bold transition-all ${
                    activeCategory === cat 
                      ? 'bg-white text-gray-900 shadow-sm' 
                      : 'text-gray-400 hover:text-gray-900'
                  }`}
                >
                  {cat}
                </button>
              ))}
            </nav>
          </div>

          <div className="flex items-center gap-4 shrink-0">
            <button 
              onClick={() => { setEditingInsight(undefined); setShowForm(true); }}
              className="bg-[#12141c] text-white flex items-center gap-2 px-6 py-2.5 rounded-full hover:scale-105 transition-all shadow-lg active:scale-95"
            >
              <Plus className="w-4 h-4" />
              <span className="text-sm font-black hidden sm:inline">记录观点</span>
            </button>
          </div>
        </div>
      </header>

      <div className="max-w-[1600px] mx-auto px-8 py-12 w-full flex flex-col lg:flex-row gap-16">
        {/* 侧边栏 */}
        <aside className="lg:w-48 space-y-10 flex-shrink-0">
          <div className="sticky top-[100px]">
             {/* 移动端分类导航（当顶栏隐藏时可见） */}
            <div className="xl:hidden mb-10">
               <h3 className="text-[11px] font-black text-gray-300 uppercase tracking-[0.2em] mb-6">分类筛选</h3>
               <div className="flex flex-wrap gap-2">
                  {CATEGORIES.map(cat => (
                    <button
                      key={cat}
                      onClick={() => setActiveCategory(cat)}
                      className={`px-4 py-2 rounded-xl text-[12px] font-bold border transition-all ${
                        activeCategory === cat 
                          ? 'bg-[#12141c] text-white border-[#12141c]' 
                          : 'bg-white text-gray-400 border-gray-100 hover:border-gray-300'
                      }`}
                    >
                      {cat}
                    </button>
                  ))}
               </div>
            </div>

            <h3 className="text-[11px] font-black text-gray-300 uppercase tracking-[0.2em] mb-6">历史归档</h3>
            <div className="space-y-1">
              <button
                onClick={() => setSelectedMonth(null)}
                className={`w-full text-left px-4 py-3 rounded-xl text-[13px] font-bold transition-all flex items-center justify-between ${
                  selectedMonth === null ? 'bg-[#12141c] text-white' : 'text-gray-400 hover:bg-gray-100'
                }`}
              >
                <span>全部记录</span>
                <span className="text-[10px] opacity-50">{insights.length}</span>
              </button>
              {timelineGroups.map(([month, count]) => (
                <button
                  key={month}
                  onClick={() => setSelectedMonth(month)}
                  className={`w-full text-left px-4 py-3 rounded-xl text-[13px] font-bold transition-all flex items-center justify-between ${
                    selectedMonth === month ? 'bg-[#12141c] text-white' : 'text-gray-400 hover:bg-gray-100'
                  }`}
                >
                  <span>{month}</span>
                  <span className="text-[10px] opacity-50">{count}</span>
                </button>
              ))}
            </div>
          </div>
        </aside>

        <main className="flex-grow">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 mb-16">
            <h2 className="text-5xl font-black text-[#12141c] tracking-tighter leading-tight italic">
              追踪行情，<br />每日洞察。
            </h2>
            <div className="flex bg-gray-100 p-1 rounded-xl border border-gray-200">
              <button onClick={() => setSortMode('category')} className={`px-5 py-2 rounded-lg text-[12px] font-black transition-all ${sortMode === 'category' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-400'}`}>
                <ListFilter className="w-3.5 h-3.5 mr-1 inline" /> 类别
              </button>
              <button onClick={() => setSortMode('timeline')} className={`px-5 py-2 rounded-lg text-[12px] font-black transition-all ${sortMode === 'timeline' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-400'}`}>
                <CalendarDays className="w-3.5 h-3.5 mr-1 inline" /> 时间
              </button>
            </div>
          </div>

          {/* 搜索结果提示 */}
          {searchQuery && (
            <div className="mb-10 text-gray-400 text-sm font-medium">
              找到 <span className="text-gray-900 font-black">{filteredInsights.length}</span> 个包含 “<span className="text-gray-900 font-black">{searchQuery}</span>” 的结果
            </div>
          )}

          {/* 活跃观点区域 */}
          {activeItems.length > 0 ? (
            <div className="space-y-16">
              {groupedActiveInsights.map(([groupLabel, groupItems]) => (
                <section key={groupLabel}>
                  <div className="flex items-center gap-4 mb-10">
                    <span className="text-[12px] font-black tracking-widest uppercase bg-[#12141c] text-white px-4 py-1.5 rounded-full">{groupLabel}</span>
                    <div className="flex-grow h-[1px] bg-gray-100" />
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
                    {groupItems.map(insight => (
                      <MarketCard 
                        key={insight.id} 
                        insight={insight} 
                        onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
                        onDelete={handleDeleteInsight}
                        onToggleCompletion={handleToggleCompletionStatus}
                      />
                    ))}
                  </div>
                </section>
              ))}
            </div>
          ) : (
            <div className="text-center py-32 border-2 border-dashed border-gray-100 rounded-[3rem]">
              <Plus className="w-10 h-10 text-gray-200 mx-auto mb-4" />
              <h3 className="text-xl font-black text-gray-900">
                {searchQuery ? '没有找到相关记录' : '暂无进行中的记录'}
              </h3>
              <p className="text-sm text-gray-400 mt-1">
                {searchQuery ? '试着换个关键词搜索' : '点击右上角“记录观点”开启追踪'}
              </p>
            </div>
          )}

          {/* 归档区域 */}
          {archivedItems.length > 0 && (
            <div className="mt-40 pt-20 border-t border-gray-100">
               <div className="flex items-center gap-4 mb-12">
                  <Archive className="w-6 h-6 text-gray-300" />
                  <h3 className="text-xl font-black text-[#12141c]">历史归档 <span className="text-gray-300 font-medium ml-2">{archivedItems.length}</span></h3>
               </div>
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8 grayscale opacity-60">
                {archivedItems.map(insight => (
                  <MarketCard 
                    key={insight.id} 
                    insight={insight} 
                    onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
                    onDelete={handleDeleteInsight}
                    onToggleCompletion={handleToggleCompletionStatus}
                  />
                ))}
              </div>
            </div>
          )}
        </main>
      </div>

      <footer className="mt-auto py-16 border-t border-gray-100 text-center">
          <p className="text-[11px] text-gray-300 font-black uppercase tracking-[0.5em]">Market Journal · 智慧记录</p>
      </footer>

      {showForm && (
        <InsightForm 
          initialData={editingInsight}
          onSave={handleSaveInsight}
          onCancel={() => { setShowForm(false); setEditingInsight(undefined); }}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { MarketInsight, Category, CompletionStatus, SortMode } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import { Plus, LayoutGrid, ListFilter, CalendarDays, Archive, Search, X } from 'lucide-react';

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>(() => {
    const saved = localStorage.getItem('trading_journal_v4');
    return saved ? JSON.parse(saved) : INITIAL_INSIGHTS;
  });

  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [sortMode, setSortMode] = useState<SortMode>('category');
  const [showForm, setShowForm] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    localStorage.setItem('trading_journal_v4', JSON.stringify(insights));
  }, [insights]);

  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    let result = insights;

    // 搜索过滤
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      result = result.filter(i => 
        i.symbol.toLowerCase().includes(query) || 
        i.focusPoints.toLowerCase().includes(query) || 
        i.strategy.toLowerCase().includes(query)
      );
    }

    // 分类过滤
    if (activeCategory !== '全部') {
      result = result.filter(i => i.category === activeCategory);
    }

    // 时间归档过滤
    if (selectedMonth) {
      result = result.filter(i => {
        const date = new Date(i.updatedAt);
        return `${date.getFullYear()}年${date.getMonth() + 1}月` === selectedMonth;
      });
    }
    return result;
  }, [insights, activeCategory, selectedMonth, searchQuery]);

  const { activeItems, archivedItems } = useMemo(() => {
    return {
      activeItems: filteredInsights.filter(i => i.completionStatus === '进行中'),
      archivedItems: filteredInsights.filter(i => i.completionStatus !== '进行中')
    };
  }, [filteredInsights]);

  const groupedActiveInsights = useMemo(() => {
    const groups: { [label: string]: MarketInsight[] } = {};
    activeItems.forEach(insight => {
      let label = sortMode === 'timeline' 
        ? new Date(insight.updatedAt).toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' })
        : insight.category;
      if (!groups[label]) groups[label] = [];
      groups[label].push(insight);
    });
    const entries = Object.entries(groups);
    return sortMode === 'category' 
      ? entries.sort((a, b) => CATEGORIES.indexOf(a[0] as any) - CATEGORIES.indexOf(b[0] as any))
      : entries.sort((a, b) => b[1][0].updatedAt - a[1][0].updatedAt);
  }, [activeItems, sortMode]);

  const handleSaveInsight = (data: Partial<MarketInsight>) => {
    if (editingInsight) {
      setInsights(prev => prev.map(i => i.id === editingInsight.id ? { ...i, ...data, updatedAt: data.updatedAt || i.updatedAt } as MarketInsight : i));
    } else {
      const newInsight: MarketInsight = {
        id: Math.random().toString(36).substr(2, 9),
        ...data as any,
        updatedAt: data.updatedAt || Date.now(),
        completionStatus: data.completionStatus || '进行中',
      };
      setInsights(prev => [newInsight, ...prev]);
    }
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = (id: string) => {
    if (window.confirm('确定要删除这条市场记录吗？')) {
      setInsights(prev => prev.filter(i => i.id !== id));
    }
  };

  const handleToggleCompletionStatus = (id: string) => {
    const statuses: CompletionStatus[] = ['进行中', '已完成', '已失效'];
    setInsights(prev => prev.map(i => {
      if (i.id === id) {
        const currentIndex = statuses.indexOf(i.completionStatus);
        const nextStatus = statuses[(currentIndex + 1) % statuses.length];
        return { ...i, completionStatus: nextStatus, updatedAt: Date.now() };
      }
      return i;
    }));
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-amber-100">
      {/* 极简顶栏 */}
      <header className="sticky top-0 z-[100] bg-white/80 backdrop-blur-xl border-b border-gray-100 px-8 h-[72px]">
        <div className="max-w-[1600px] mx-auto flex items-center justify-between h-full gap-8">
          <div className="flex items-center gap-3 shrink-0">
            <div className="bg-[#12141c] w-8 h-8 rounded-lg flex items-center justify-center">
              <LayoutGrid className="w-4 h-4 text-white" />
            </div>
            <h1 className="text-lg font-black text-[#12141c] tracking-tighter hidden sm:block">市场周刊</h1>
          </div>

          <div className="flex-grow flex items-center gap-4 max-w-3xl">
            {/* 搜索框 */}
            <div className="relative group flex-grow">
              <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                <Search className={`w-4 h-4 transition-colors ${searchQuery ? 'text-gray-900' : 'text-gray-300'}`} />
              </div>
              <input
                type="text"
                className="w-full bg-gray-100/50 border border-transparent focus:bg-white focus:border-gray-200 py-2.5 pl-10 pr-10 rounded-2xl text-[13px] font-bold outline-none transition-all placeholder:text-gray-300"
                placeholder="搜索资产代码、观察或策略..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
              {searchQuery && (
                <button 
                  onClick={() => setSearchQuery('')}
                  className="absolute inset-y-0 right-0 pr-3 flex items-center text-gray-300 hover:text-gray-900 transition-colors"
                >
                  <X className="w-4 h-4" />
                </button>
              )}
            </div>

            <nav className="hidden xl:flex items-center gap-1 bg-gray-100/50 p-1 rounded-2xl shrink-0">
              {CATEGORIES.map(cat => (
                <button
                  key={cat}
                  onClick={() => setActiveCategory(cat)}
                  className={`px-5 py-2 rounded-xl text-[13px] font-bold transition-all ${
                    activeCategory === cat 
                      ? 'bg-white text-gray-900 shadow-sm' 
                      : 'text-gray-400 hover:text-gray-900'
                  }`}
                >
                  {cat}
                </button>
              ))}
            </nav>
          </div>

          <div className="flex items-center gap-4 shrink-0">
            <button 
              onClick={() => { setEditingInsight(undefined); setShowForm(true); }}
              className="bg-[#12141c] text-white flex items-center gap-2 px-6 py-2.5 rounded-full hover:scale-105 transition-all shadow-lg active:scale-95"
            >
              <Plus className="w-4 h-4" />
              <span className="text-sm font-black hidden sm:inline">记录观点</span>
            </button>
          </div>
        </div>
      </header>

      <div className="max-w-[1600px] mx-auto px-8 py-12 w-full flex flex-col lg:flex-row gap-16">
        {/* 侧边栏 */}
        <aside className="lg:w-48 space-y-10 flex-shrink-0">
          <div className="sticky top-[100px]">
             {/* 移动端分类导航（当顶栏隐藏时可见） */}
            <div className="xl:hidden mb-10">
               <h3 className="text-[11px] font-black text-gray-300 uppercase tracking-[0.2em] mb-6">分类筛选</h3>
               <div className="flex flex-wrap gap-2">
                  {CATEGORIES.map(cat => (
                    <button
                      key={cat}
                      onClick={() => setActiveCategory(cat)}
                      className={`px-4 py-2 rounded-xl text-[12px] font-bold border transition-all ${
                        activeCategory === cat 
                          ? 'bg-[#12141c] text-white border-[#12141c]' 
                          : 'bg-white text-gray-400 border-gray-100 hover:border-gray-300'
                      }`}
                    >
                      {cat}
                    </button>
                  ))}
               </div>
            </div>

            <h3 className="text-[11px] font-black text-gray-300 uppercase tracking-[0.2em] mb-6">历史归档</h3>
            <div className="space-y-1">
              <button
                onClick={() => setSelectedMonth(null)}
                className={`w-full text-left px-4 py-3 rounded-xl text-[13px] font-bold transition-all flex items-center justify-between ${
                  selectedMonth === null ? 'bg-[#12141c] text-white' : 'text-gray-400 hover:bg-gray-100'
                }`}
              >
                <span>全部记录</span>
                <span className="text-[10px] opacity-50">{insights.length}</span>
              </button>
              {timelineGroups.map(([month, count]) => (
                <button
                  key={month}
                  onClick={() => setSelectedMonth(month)}
                  className={`w-full text-left px-4 py-3 rounded-xl text-[13px] font-bold transition-all flex items-center justify-between ${
                    selectedMonth === month ? 'bg-[#12141c] text-white' : 'text-gray-400 hover:bg-gray-100'
                  }`}
                >
                  <span>{month}</span>
                  <span className="text-[10px] opacity-50">{count}</span>
                </button>
              ))}
            </div>
          </div>
        </aside>

        <main className="flex-grow">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 mb-16">
            <h2 className="text-5xl font-black text-[#12141c] tracking-tighter leading-tight italic">
              追踪行情，<br />每日洞察。
            </h2>
            <div className="flex bg-gray-100 p-1 rounded-xl border border-gray-200">
              <button onClick={() => setSortMode('category')} className={`px-5 py-2 rounded-lg text-[12px] font-black transition-all ${sortMode === 'category' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-400'}`}>
                <ListFilter className="w-3.5 h-3.5 mr-1 inline" /> 类别
              </button>
              <button onClick={() => setSortMode('timeline')} className={`px-5 py-2 rounded-lg text-[12px] font-black transition-all ${sortMode === 'timeline' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-400'}`}>
                <CalendarDays className="w-3.5 h-3.5 mr-1 inline" /> 时间
              </button>
            </div>
          </div>

          {/* 搜索结果提示 */}
          {searchQuery && (
            <div className="mb-10 text-gray-400 text-sm font-medium">
              找到 <span className="text-gray-900 font-black">{filteredInsights.length}</span> 个包含 “<span className="text-gray-900 font-black">{searchQuery}</span>” 的结果
            </div>
          )}

          {/* 活跃观点区域 */}
          {activeItems.length > 0 ? (
            <div className="space-y-16">
              {groupedActiveInsights.map(([groupLabel, groupItems]) => (
                <section key={groupLabel}>
                  <div className="flex items-center gap-4 mb-10">
                    <span className="text-[12px] font-black tracking-widest uppercase bg-[#12141c] text-white px-4 py-1.5 rounded-full">{groupLabel}</span>
                    <div className="flex-grow h-[1px] bg-gray-100" />
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
                    {groupItems.map(insight => (
                      <MarketCard 
                        key={insight.id} 
                        insight={insight} 
                        onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
                        onDelete={handleDeleteInsight}
                        onToggleCompletion={handleToggleCompletionStatus}
                      />
                    ))}
                  </div>
                </section>
              ))}
            </div>
          ) : (
            <div className="text-center py-32 border-2 border-dashed border-gray-100 rounded-[3rem]">
              <Plus className="w-10 h-10 text-gray-200 mx-auto mb-4" />
              <h3 className="text-xl font-black text-gray-900">
                {searchQuery ? '没有找到相关记录' : '暂无进行中的记录'}
              </h3>
              <p className="text-sm text-gray-400 mt-1">
                {searchQuery ? '试着换个关键词搜索' : '点击右上角“记录观点”开启追踪'}
              </p>
            </div>
          )}

          {/* 归档区域 */}
          {archivedItems.length > 0 && (
            <div className="mt-40 pt-20 border-t border-gray-100">
               <div className="flex items-center gap-4 mb-12">
                  <Archive className="w-6 h-6 text-gray-300" />
                  <h3 className="text-xl font-black text-[#12141c]">历史归档 <span className="text-gray-300 font-medium ml-2">{archivedItems.length}</span></h3>
               </div>
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8 grayscale opacity-60">
                {archivedItems.map(insight => (
                  <MarketCard 
                    key={insight.id} 
                    insight={insight} 
                    onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
                    onDelete={handleDeleteInsight}
                    onToggleCompletion={handleToggleCompletionStatus}
                  />
                ))}
              </div>
            </div>
          )}
        </main>
      </div>

      {showForm && (
        <InsightForm 
          initialData={editingInsight}
          onSave={handleSaveInsight}
          onCancel={() => { setShowForm(false); setEditingInsight(undefined); }}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { MarketInsight, Category, CompletionStatus, SortMode } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import { Plus, LayoutGrid, ListFilter, CalendarDays, Archive, Search, X, Lock } from 'lucide-react';

const ADMIN_PASSWORD = "8888"; // 预设管理员密码

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>(() => {
    const saved = localStorage.getItem('trading_journal_v4');
    return saved ? JSON.parse(saved) : INITIAL_INSIGHTS;
  });

  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [sortMode, setSortMode] = useState<SortMode>('category');
  const [showForm, setShowForm] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);
  const [searchQuery, setSearchQuery] = useState('');

  // 权限控制状态
  const [isAdmin, setIsAdmin] = useState(() => localStorage.getItem('is_admin') === 'true');
  const [clickCount, setClickCount] = useState(0);

  useEffect(() => {
    localStorage.setItem('trading_journal_v4', JSON.stringify(insights));
  }, [insights]);

  // 管理员入口触发器
  const handleLogoClick = () => {
    if (isAdmin) return;
    const newCount = clickCount + 1;
    if (newCount >= 5) {
      const pwd = prompt("请输入管理员密码解锁编辑功能：");
      if (pwd === ADMIN_PASSWORD) {
        setIsAdmin(true);
        localStorage.setItem('is_admin', 'true');
        setClickCount(0);
        alert("已切换至管理员模式");
      } else {
        setClickCount(0);
        alert("密码错误");
      }
    } else {
      setClickCount(newCount);
    }
  };

  const handleLogout = () => {
    setIsAdmin(false);
    localStorage.removeItem('is_admin');
  };

  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    let result = insights;
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      result = result.filter(i => 
        i.symbol.toLowerCase().includes(query) || 
        i.focusPoints.toLowerCase().includes(query) || 
        i.strategy.toLowerCase().includes(query)
      );
    }
    if (activeCategory !== '全部') {
      result = result.filter(i => i.category === activeCategory);
    }
    if (selectedMonth) {
      result = result.filter(i => {
        const date = new Date(i.updatedAt);
        return `${date.getFullYear()}年${date.getMonth() + 1}月` === selectedMonth;
      });
    }
    return result;
  }, [insights, activeCategory, selectedMonth, searchQuery]);

  const { activeItems, archivedItems } = useMemo(() => {
    return {
      activeItems: filteredInsights.filter(i => i.completionStatus === '进行中'),
      archivedItems: filteredInsights.filter(i => i.completionStatus !== '进行中')
    };
  }, [filteredInsights]);

  const groupedActiveInsights = useMemo(() => {
    const groups: { [label: string]: MarketInsight[] } = {};
    activeItems.forEach(insight => {
      let label = sortMode === 'timeline' 
        ? new Date(insight.updatedAt).toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' })
        : insight.category;
      if (!groups[label]) groups[label] = [];
      groups[label].push(insight);
    });
    const entries = Object.entries(groups);
    return sortMode === 'category' 
      ? entries.sort((a, b) => CATEGORIES.indexOf(a[0] as any) - CATEGORIES.indexOf(b[0] as any))
      : entries.sort((a, b) => b[1][0].updatedAt - a[1][0].updatedAt);
  }, [activeItems, sortMode]);

  const handleSaveInsight = (data: Partial<MarketInsight>) => {
    if (!isAdmin) return;
    if (editingInsight) {
      setInsights(prev => prev.map(i => i.id === editingInsight.id ? { ...i, ...data, updatedAt: data.updatedAt || i.updatedAt } as MarketInsight : i));
    } else {
      const newInsight: MarketInsight = {
        id: Math.random().toString(36).substr(2, 9),
        ...data as any,
        updatedAt: data.updatedAt || Date.now(),
        completionStatus: data.completionStatus || '进行中',
      };
      setInsights(prev => [newInsight, ...prev]);
    }
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = (id: string) => {
    if (!isAdmin) return;
    if (window.confirm('确定要删除这条市场记录吗？')) {
      setInsights(prev => prev.filter(i => i.id !== id));
    }
  };

  const handleToggleCompletionStatus = (id: string) => {
    if (!isAdmin) return;
    const statuses: CompletionStatus[] = ['进行中', '已完成', '已失效'];
    setInsights(prev => prev.map(i => {
      if (i.id === id) {
        const currentIndex = statuses.indexOf(i.completionStatus);
        const nextStatus = statuses[(currentIndex + 1) % statuses.length];
        return { ...i, completionStatus: nextStatus, updatedAt: Date.now() };
      }
      return i;
    }));
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-amber-100">
      {/* 极简顶栏 */}
      <header className="sticky top-0 z-[100] bg-white/80 backdrop-blur-xl border-b border-gray-100 px-8 h-[72px]">
        <div className="max-w-[1600px] mx-auto flex items-center justify-between h-full gap-8">
          <div className="flex items-center gap-3 shrink-0">
            <button 
              onClick={handleLogoClick}
              className={`w-8 h-8 rounded-lg flex items-center justify-center transition-all active:scale-90 ${isAdmin ? 'bg-amber-500 shadow-lg shadow-amber-200' : 'bg-[#12141c]'}`}
            >
              <LayoutGrid className="w-4 h-4 text-white" />
            </button>
            <div className="flex flex-col">
              <h1 className="text-lg font-black text-[#12141c] tracking-tighter hidden sm:block">市场周刊</h1>
              {!isAdmin && <span className="text-[9px] font-bold text-gray-400 uppercase tracking-widest hidden sm:block">只读查阅模式</span>}
            </div>
          </div>

          <div className="flex-grow flex items-center gap-4 max-w-3xl">
            {/* 搜索框 */}
            <div className="relative group flex-grow">
              <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                <Search className={`w-4 h-4 transition-colors ${searchQuery ? 'text-gray-900' : 'text-gray-300'}`} />
              </div>
              <input
                type="text"
                className="w-full bg-gray-100/50 border border-transparent focus:bg-white focus:border-gray-200 py-2.5 pl-10 pr-10 rounded-2xl text-[13px] font-bold outline-none transition-all placeholder:text-gray-300"
                placeholder="搜索资产代码、观察或策略..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
              {searchQuery && (
                <button 
                  onClick={() => setSearchQuery('')}
                  className="absolute inset-y-0 right-0 pr-3 flex items-center text-gray-300 hover:text-gray-900 transition-colors"
                >
                  <X className="w-4 h-4" />
                </button>
              )}
            </div>

            <nav className="hidden xl:flex items-center gap-1 bg-gray-100/50 p-1 rounded-2xl shrink-0">
              {CATEGORIES.map(cat => (
                <button
                  key={cat}
                  onClick={() => setActiveCategory(cat)}
                  className={`px-5 py-2 rounded-xl text-[13px] font-bold transition-all ${
                    activeCategory === cat 
                      ? 'bg-white text-gray-900 shadow-sm' 
                      : 'text-gray-400 hover:text-gray-900'
                  }`}
                >
                  {cat}
                </button>
              ))}
            </nav>
          </div>

          <div className="flex items-center gap-4 shrink-0">
            {isAdmin ? (
              <div className="flex items-center gap-2">
                <button 
                  onClick={() => { setEditingInsight(undefined); setShowForm(true); }}
                  className="bg-[#12141c] text-white flex items-center gap-2 px-6 py-2.5 rounded-full hover:scale-105 transition-all shadow-lg active:scale-95"
                >
                  <Plus className="w-4 h-4" />
                  <span className="text-sm font-black hidden sm:inline">记录观点</span>
                </button>
                <button onClick={handleLogout} className="p-2 text-gray-300 hover:text-red-500 transition-colors">
                   <Lock className="w-4 h-4" />
                </button>
              </div>
            ) : (
              <div className="px-4 py-2 border border-gray-100 rounded-full bg-gray-50/50">
                <span className="text-[11px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                  <div className="w-1.5 h-1.5 rounded-full bg-gray-300 animate-pulse" />
                  只读视图
                </span>
              </div>
            )}
          </div>
        </div>
      </header>

      <div className="max-w-[1600px] mx-auto px-8 py-12 w-full flex flex-col lg:flex-row gap-16">
        <aside className="lg:w-48 space-y-10 flex-shrink-0">
          <div className="sticky top-[100px]">
            <div className="xl:hidden mb-10">
               <h3 className="text-[11px] font-black text-gray-300 uppercase tracking-[0.2em] mb-6">分类筛选</h3>
               <div className="flex flex-wrap gap-2">
                  {CATEGORIES.map(cat => (
                    <button
                      key={cat}
                      onClick={() => setActiveCategory(cat)}
                      className={`px-4 py-2 rounded-xl text-[12px] font-bold border transition-all ${
                        activeCategory === cat 
                          ? 'bg-[#12141c] text-white border-[#12141c]' 
                          : 'bg-white text-gray-400 border-gray-100 hover:border-gray-300'
                      }`}
                    >
                      {cat}
                    </button>
                  ))}
               </div>
            </div>

            <h3 className="text-[11px] font-black text-gray-300 uppercase tracking-[0.2em] mb-6">历史归档</h3>
            <div className="space-y-1">
              <button
                onClick={() => setSelectedMonth(null)}
                className={`w-full text-left px-4 py-3 rounded-xl text-[13px] font-bold transition-all flex items-center justify-between ${
                  selectedMonth === null ? 'bg-[#12141c] text-white' : 'text-gray-400 hover:bg-gray-100'
                }`}
              >
                <span>全部记录</span>
                <span className="text-[10px] opacity-50">{insights.length}</span>
              </button>
              {timelineGroups.map(([month, count]) => (
                <button
                  key={month}
                  onClick={() => setSelectedMonth(month)}
                  className={`w-full text-left px-4 py-3 rounded-xl text-[13px] font-bold transition-all flex items-center justify-between ${
                    selectedMonth === month ? 'bg-[#12141c] text-white' : 'text-gray-400 hover:bg-gray-100'
                  }`}
                >
                  <span>{month}</span>
                  <span className="text-[10px] opacity-50">{count}</span>
                </button>
              ))}
            </div>
          </div>
        </aside>

        <main className="flex-grow">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 mb-16">
            <h2 className="text-5xl font-black text-[#12141c] tracking-tighter leading-tight italic">
              追踪行情，<br />每日洞察。
            </h2>
            <div className="flex bg-gray-100 p-1 rounded-xl border border-gray-200">
              <button onClick={() => setSortMode('category')} className={`px-5 py-2 rounded-lg text-[12px] font-black transition-all ${sortMode === 'category' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-400'}`}>
                <ListFilter className="w-3.5 h-3.5 mr-1 inline" /> 类别
              </button>
              <button onClick={() => setSortMode('timeline')} className={`px-5 py-2 rounded-lg text-[12px] font-black transition-all ${sortMode === 'timeline' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-400'}`}>
                <CalendarDays className="w-3.5 h-3.5 mr-1 inline" /> 时间
              </button>
            </div>
          </div>

          {searchQuery && (
            <div className="mb-10 text-gray-400 text-sm font-medium">
              找到 <span className="text-gray-900 font-black">{filteredInsights.length}</span> 个包含 “<span className="text-gray-900 font-black">{searchQuery}</span>” 的结果
            </div>
          )}

          {activeItems.length > 0 ? (
            <div className="space-y-16">
              {groupedActiveInsights.map(([groupLabel, groupItems]) => (
                <section key={groupLabel}>
                  <div className="flex items-center gap-4 mb-10">
                    <span className="text-[12px] font-black tracking-widest uppercase bg-[#12141c] text-white px-4 py-1.5 rounded-full">{groupLabel}</span>
                    <div className="flex-grow h-[1px] bg-gray-100" />
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
                    {groupItems.map(insight => (
                      <MarketCard 
                        key={insight.id} 
                        insight={insight} 
                        onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}}
                        onDelete={isAdmin ? handleDeleteInsight : () => {}}
                        onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}}
                        isEditable={isAdmin}
                      />
                    ))}
                  </div>
                </section>
              ))}
            </div>
          ) : (
            <div className="text-center py-32 border-2 border-dashed border-gray-100 rounded-[3rem]">
              <Plus className="w-10 h-10 text-gray-200 mx-auto mb-4" />
              <h3 className="text-xl font-black text-gray-900">
                {searchQuery ? '没有找到相关记录' : '暂无进行中的记录'}
              </h3>
              <p className="text-sm text-gray-400 mt-1">
                {searchQuery ? '试着换个关键词搜索' : isAdmin ? '点击右上角“记录观点”开启追踪' : '目前没有活跃观点'}
              </p>
            </div>
          )}

          {archivedItems.length > 0 && (
            <div className="mt-40 pt-20 border-t border-gray-100">
               <div className="flex items-center gap-4 mb-12">
                  <Archive className="w-6 h-6 text-gray-300" />
                  <h3 className="text-xl font-black text-[#12141c]">历史归档 <span className="text-gray-300 font-medium ml-2">{archivedItems.length}</span></h3>
               </div>
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8 grayscale opacity-60">
                {archivedItems.map(insight => (
                  <MarketCard 
                    key={insight.id} 
                    insight={insight} 
                    onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}}
                    onDelete={isAdmin ? handleDeleteInsight : () => {}}
                    onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}}
                    isEditable={isAdmin}
                  />
                ))}
              </div>
            </div>
          )}
        </main>
      </div>

      {showForm && isAdmin && (
        <InsightForm 
          initialData={editingInsight}
          onSave={handleSaveInsight}
          onCancel={() => { setShowForm(false); setEditingInsight(undefined); }}
        />
      )}
    </div>
  );
};

export default App;

import React from 'react';
import { MarketInsight, AssetStatus, CompletionStatus } from '../types';
import { Edit2, Trash2, Calendar, TrendingUp, TrendingDown, Activity, Target, ChevronRight, CheckCircle2, XCircle, Clock } from 'lucide-react';

interface MarketCardProps {
  insight: MarketInsight;
  onEdit: (insight: MarketInsight) => void;
  onDelete: (id: string) => void;
  onToggleCompletion: (id: string) => void;
  isEditable?: boolean;
}

const getAssetStatusStyle = (status: AssetStatus) => {
  switch (status) {
    case '看涨': return {
      color: 'text-red-500',
      bg: 'bg-red-50',
      border: 'border-red-100',
      icon: <TrendingUp className="w-4 h-4" />
    };
    case '看跌': return {
      color: 'text-emerald-500',
      bg: 'bg-emerald-50',
      border: 'border-emerald-100',
      icon: <TrendingDown className="w-4 h-4" />
    };
    default: return {
      color: 'text-blue-500',
      bg: 'bg-blue-50',
      border: 'border-blue-100',
      icon: <Activity className="w-4 h-4" />
    };
  }
};

const getCompletionStatusStyle = (status: CompletionStatus) => {
  switch (status) {
    case '已完成': return {
      label: '已完成',
      color: 'text-emerald-600',
      bg: 'bg-emerald-50',
      icon: <CheckCircle2 className="w-3 h-3" />
    };
    case '已失效': return {
      label: '已失效',
      color: 'text-slate-500',
      bg: 'bg-slate-50',
      icon: <XCircle className="w-3 h-3" />
    };
    default: return {
      label: '进行中',
      color: 'text-red-600',
      bg: 'bg-red-50',
      icon: <Clock className="w-3 h-3" />
    };
  }
};

const MarketCard: React.FC<MarketCardProps> = ({ insight, onEdit, onDelete, onToggleCompletion, isEditable = false }) => {
  const date = new Date(insight.updatedAt).toLocaleDateString('zh-CN', {
    month: 'short',
    day: 'numeric'
  });

  const assetStyle = getAssetStatusStyle(insight.status);
  const completionStyle = getCompletionStatusStyle(insight.completionStatus);
  const isArchived = insight.completionStatus !== '进行中';

  return (
    <div className={`group relative bg-white border border-gray-100 rounded-[2.5rem] p-8 transition-all duration-500 hover:shadow-[0_30px_60px_-15px_rgba(0,0,0,0.08)] flex flex-col min-h-[420px] overflow-hidden ${isArchived ? 'opacity-75 hover:opacity-100' : ''}`}>

      {/* 顶部标识 */}
      <div className="flex justify-between items-start mb-8 relative z-10">
        <div>
          <div className="flex items-center gap-2 mb-1">
             <h3 className="text-3xl font-black text-[#12141c] tracking-tighter">{insight.symbol}</h3>
             <span className={`px-4 py-1.5 rounded-lg text-[16px] font-black uppercase tracking-wider ${assetStyle.bg} ${assetStyle.color}`}>
                {insight.status}
             </span>
          </div>
          <div className="flex items-center text-[12px] text-gray-400 font-bold gap-2">
            <Calendar className="w-3.5 h-3.5" />
            {date}
          </div>
        </div>

        <button 
          onClick={() => isEditable && onToggleCompletion(insight.id)}
          disabled={!isEditable}
          className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[10px] font-black border transition-all ${isEditable ? 'hover:scale-105 active:scale-95 cursor-pointer' : 'cursor-default'} ${completionStyle.bg} ${completionStyle.color} border-current/10 bg-white/50 backdrop-blur-sm`}
        >
          {completionStyle.icon}
          {completionStyle.label}
        </button>
      </div>

      {/* 内容主体 */}
      <div className="flex-grow space-y-6 relative z-10">
        <div>
          <div className="mb-2">
            <span className="inline-block px-1 bg-amber-100/80 text-[18px] font-black text-[#12141c] uppercase tracking-widest">
              核心观察
            </span>
          </div>
          <p className="text-[15px] font-medium leading-relaxed text-gray-700">
            {insight.focusPoints}
          </p>
        </div>

        {insight.entryLevel && (
          <div className="flex items-center gap-3 text-gray-900">
            <Target className="w-4 h-4 text-gray-400" />
            <span className="text-[14px] font-black underline decoration-gray-200 decoration-2 underline-offset-4">点位: {insight.entryLevel}</span>
          </div>
        )}

        <div className="pt-4 border-t border-gray-50">
          <div className="mb-2">
            <span className="inline-block px-1 bg-amber-100/80 text-[18px] font-black text-[#12141c] uppercase tracking-widest">
              应对策略
            </span>
          </div>
          <div className="flex items-start gap-3">
             <ChevronRight className={`w-4 h-4 mt-0.5 ${assetStyle.color}`} />
             <p className="text-[15px] font-bold text-[#12141c] leading-snug">
               {insight.strategy}
             </p>
          </div>
        </div>
      </div>

      {/* 底部工具 */}
      <div className={`mt-8 pt-6 border-t border-gray-50 flex justify-between items-center transition-all duration-300 relative z-10 ${isEditable ? 'opacity-0 group-hover:opacity-100' : 'opacity-100'}`}>
        <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest bg-gray-50/80 backdrop-blur-sm px-3 py-1 rounded-lg">{insight.category}</span>

        {isEditable && (
          <div className="flex gap-1">
            <button 
              onClick={() => onEdit(insight)}
              className="p-2.5 text-gray-400 hover:text-[#12141c] hover:bg-gray-100 rounded-xl transition-all"
            >
              <Edit2 className="w-4 h-4" />
            </button>
            <button 
              onClick={() => onDelete(insight.id)}
              className="p-2.5 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"
            >
              <Trash2 className="w-4 h-4" />
            </button>
          </div>
        )}
      </div>

      {/* 右下角圆形灰色状态指示器 */}
      {isArchived && (
        <div className="absolute bottom-6 right-6 flex items-center justify-center w-10 h-10 rounded-full bg-gray-100/50 backdrop-blur-sm border border-gray-200/50 transition-all duration-300 group-hover:scale-110">
           {insight.completionStatus === '已完成' ? (
             <CheckCircle2 className="w-5 h-5 text-gray-400" />
           ) : (
             <XCircle className="w-5 h-5 text-gray-400" />
           )}
        </div>
      )}
    </div>
  );
};

export default MarketCard;

import React, { useState, useEffect, useMemo } from 'react';
import { MarketInsight, Category, CompletionStatus, SortMode } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import { Plus, LayoutGrid, ListFilter, CalendarDays, Archive, Search, X, Lock } from 'lucide-react';

const ADMIN_PASSWORD = "8888"; // 预设管理员密码

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>(() => {
    const saved = localStorage.getItem('trading_journal_v4');
    return saved ? JSON.parse(saved) : INITIAL_INSIGHTS;
  });

  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [sortMode, setSortMode] = useState<SortMode>('category');
  const [showForm, setShowForm] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);
  const [searchQuery, setSearchQuery] = useState('');

  // 权限控制状态
  const [isAdmin, setIsAdmin] = useState(() => localStorage.getItem('is_admin') === 'true');
  const [clickCount, setClickCount] = useState(0);

  useEffect(() => {
    localStorage.setItem('trading_journal_v4', JSON.stringify(insights));
  }, [insights]);

  // 管理员入口触发器
  const handleLogoClick = () => {
    if (isAdmin) return;
    const newCount = clickCount + 1;
    if (newCount >= 5) {
      const pwd = prompt("请输入管理员密码解锁编辑功能：");
      if (pwd === ADMIN_PASSWORD) {
        setIsAdmin(true);
        localStorage.setItem('is_admin', 'true');
        setClickCount(0);
        alert("已切换至管理员模式");
      } else {
        setClickCount(0);
        alert("密码错误");
      }
    } else {
      setClickCount(newCount);
    }
  };

  const handleLogout = () => {
    setIsAdmin(false);
    localStorage.removeItem('is_admin');
  };

  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    let result = insights;
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      result = result.filter(i => 
        i.symbol.toLowerCase().includes(query) || 
        i.focusPoints.toLowerCase().includes(query) || 
        i.strategy.toLowerCase().includes(query)
      );
    }
    if (activeCategory !== '全部') {
      result = result.filter(i => i.category === activeCategory);
    }
    if (selectedMonth) {
      result = result.filter(i => {
        const date = new Date(i.updatedAt);
        return `${date.getFullYear()}年${date.getMonth() + 1}月` === selectedMonth;
      });
    }
    return result;
  }, [insights, activeCategory, selectedMonth, searchQuery]);

  const { activeItems, archivedItems } = useMemo(() => {
    return {
      activeItems: filteredInsights.filter(i => i.completionStatus === '进行中'),
      archivedItems: filteredInsights.filter(i => i.completionStatus !== '进行中')
    };
  }, [filteredInsights]);

  const groupedActiveInsights = useMemo(() => {
    const groups: { [label: string]: MarketInsight[] } = {};
    activeItems.forEach(insight => {
      let label = sortMode === 'timeline' 
        ? new Date(insight.updatedAt).toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' })
        : insight.category;
      if (!groups[label]) groups[label] = [];
      groups[label].push(insight);
    });
    const entries = Object.entries(groups);
    return sortMode === 'category' 
      ? entries.sort((a, b) => CATEGORIES.indexOf(a[0] as any) - CATEGORIES.indexOf(b[0] as any))
      : entries.sort((a, b) => b[1][0].updatedAt - a[1][0].updatedAt);
  }, [activeItems, sortMode]);

  const handleSaveInsight = (data: Partial<MarketInsight>) => {
    if (!isAdmin) return;
    if (editingInsight) {
      setInsights(prev => prev.map(i => i.id === editingInsight.id ? { ...i, ...data, updatedAt: data.updatedAt || i.updatedAt } as MarketInsight : i));
    } else {
      const newInsight: MarketInsight = {
        id: Math.random().toString(36).substr(2, 9),
        ...data as any,
        updatedAt: data.updatedAt || Date.now(),
        completionStatus: data.completionStatus || '进行中',
      };
      setInsights(prev => [newInsight, ...prev]);
