      setInsights(prev => prev.filter(i => i.id !== id));
    }
  };

  const handleToggleCompletionStatus = (id: string) => {
    if (!isAdmin) return;
    const statuses: CompletionStatus[] = ['进行中', '已完成', '已失效'];
    setInsights(prev => prev.map(i => {
      if (i.id === id) {
        const currentIndex = statuses.indexOf(i.completionStatus);
        const nextStatus = statuses[(currentIndex + 1) % statuses.length];
        return { ...i, completionStatus: nextStatus, updatedAt: Date.now() };
      }
      return i;
    }));
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-amber-100">
