            >
              <LayoutGrid className="w-4 h-4 text-white" />
            </button>
            <div className="flex flex-col">
              <h1 className="text-lg font-black text-[#12141c] tracking-tighter hidden sm:block">市场周刊</h1>
            </div>
          </div>

          <div className="flex-grow flex items-center gap-4 max-w-3xl">
            {/* 搜索框 */}
            <div className="relative group flex-grow">
              <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                <Search className={`w-4 h-4 transition-colors ${searchQuery ? 'text-gray-900' : 'text-gray-300'}`} />
              </div>
              <input
                type="text"
                className="w-full bg-gray-100/50 border border-transparent focus:bg-white focus:border-gray-200 py-2.5 pl-10 pr-10 rounded-2xl text-[13px] font-bold outline-none transition-all placeholder:text-gray-300"
                placeholder="搜索资产代码、观察或策略..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
              {searchQuery && (
                <button 
                  onClick={() => setSearchQuery('')}
                  className="absolute inset-y-0 right-0 pr-3 flex items-center text-gray-300 hover:text-gray-900 transition-colors"
                >
                  <X className="w-4 h-4" />
                </button>
              )}
            </div>

            <nav className="hidden xl:flex items-center gap-1 bg-gray-100/50 p-1 rounded-2xl shrink-0">
              {CATEGORIES.map(cat => (
                <button
                  key={cat}
                  onClick={() => setActiveCategory(cat)}
                  className={`px-5 py-2 rounded-xl text-[13px] font-bold transition-all ${
                    activeCategory === cat 
                      ? 'bg-white text-gray-900 shadow-sm' 
                      : 'text-gray-400 hover:text-gray-900'
                  }`}
                >
                  {cat}
                </button>
              ))}
            </nav>
          </div>

          <div className="flex items-center gap-4 shrink-0">
            {isAdmin && (
              <div className="flex items-center gap-2">
                <button 
                  onClick={() => { setEditingInsight(undefined); setShowForm(true); }}
                  className="bg-[#12141c] text-white flex items-center gap-2 px-6 py-2.5 rounded-full hover:scale-105 transition-all shadow-lg active:scale-95"
                >
                  <Plus className="w-4 h-4" />
                  <span className="text-sm font-black hidden sm:inline">记录观点</span>
                </button>
                <button onClick={handleLogout} className="p-2 text-gray-300 hover:text-red-500 transition-colors">
                   <Lock className="w-4 h-4" />
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      <div className="max-w-[1600px] mx-auto px-8 py-12 w-full flex flex-col lg:flex-row gap-16">
        <aside className="lg:w-48 space-y-10 flex-shrink-0">
          <div className="sticky top-[100px]">
            <div className="xl:hidden mb-10">
               <h3 className="text-[11px] font-black text-gray-300 uppercase tracking-[0.2em] mb-6">分类筛选</h3>
               <div className="flex flex-wrap gap-2">
                  {CATEGORIES.map(cat => (
                    <button
                      key={cat}
                      onClick={() => setActiveCategory(cat)}
                      className={`px-4 py-2 rounded-xl text-[12px] font-bold border transition-all ${
                        activeCategory === cat 
                          ? 'bg-[#12141c] text-white border-[#12141c]' 
                          : 'bg-white text-gray-400 border-gray-100 hover:border-gray-300'
                      }`}
                    >
                      {cat}
                    </button>
                  ))}
               </div>
            </div>

            <h3 className="text-[11px] font-black text-gray-300 uppercase tracking-[0.2em] mb-6">历史归档</h3>
            <div className="space-y-1">
              <button
                onClick={() => setSelectedMonth(null)}
                className={`w-full text-left px-4 py-3 rounded-xl text-[13px] font-bold transition-all flex items-center justify-between ${
                  selectedMonth === null ? 'bg-[#12141c] text-white' : 'text-gray-400 hover:bg-gray-100'
                }`}
              >
                <span>全部记录</span>
                <span className="text-[10px] opacity-50">{insights.length}</span>
