          </div>
        </aside>

        <main className="flex-grow">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 mb-16">
            <h2 className="text-5xl font-black text-[#12141c] tracking-tighter leading-tight italic">
              追踪行情，<br />每日洞察。
            </h2>
            <div className="flex bg-gray-100 p-1 rounded-xl border border-gray-200">
              <button onClick={() => setSortMode('category')} className={`px-5 py-2 rounded-lg text-[12px] font-black transition-all ${sortMode === 'category' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-400'}`}>
                <ListFilter className="w-3.5 h-3.5 mr-1 inline" /> 类别
              </button>
              <button onClick={() => setSortMode('timeline')} className={`px-5 py-2 rounded-lg text-[12px] font-black transition-all ${sortMode === 'timeline' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-400'}`}>
