                        onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}}
                        onDelete={isAdmin ? handleDeleteInsight : () => {}}
                        onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}}
                        isEditable={isAdmin}
