import { createClient } from '@supabase/supabase-js';

// 这些变量需要在 Netlify 的环境变量设置中配置
const supabaseUrl = process.env.SUPABASE_URL || '';
const supabaseAnonKey = process.env.SUPABASE_ANON_KEY || '';

export const supabase = createClient(supabaseUrl, supabaseAnonKey);

import React, { useState, useEffect, useMemo } from 'react';
import { MarketInsight, Category, CompletionStatus, SortMode } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import { supabase } from './services/supabaseClient';
import { Plus, LayoutGrid, ListFilter, CalendarDays, Archive, Search, X, Lock, RefreshCw } from 'lucide-react';

const ADMIN_PASSWORD = "8888"; 

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [sortMode, setSortMode] = useState<SortMode>('category');
  const [showForm, setShowForm] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);
  const [searchQuery, setSearchQuery] = useState('');

  const [isAdmin, setIsAdmin] = useState(() => localStorage.getItem('is_admin') === 'true');
  const [clickCount, setClickCount] = useState(0);

  // 从数据库加载数据
  const fetchInsights = async () => {
    setLoading(true);
    const { data, error } = await supabase
      .from('insights')
      .select('*')
      .order('updated_at', { ascending: false });

    if (error) {
      console.error('Error fetching insights:', error);
      // 如果报错且没数据，先用初始数据兜底
      if (insights.length === 0) setInsights(INITIAL_INSIGHTS);
    } else {
      // 数据库字段映射回前端格式
      const mappedData = (data || []).map(item => ({
        id: item.id,
        symbol: item.symbol,
        category: item.category,
        status: item.status as any,
        focusPoints: item.focus_points,
        strategy: item.strategy,
        entryLevel: item.entry_level,
        updatedAt: item.updated_at,
        completionStatus: item.completion_status as any
      }));
      setInsights(mappedData);
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchInsights();
  }, []);

  const handleLogoClick = () => {
    if (isAdmin) return;
    const newCount = clickCount + 1;
    if (newCount >= 5) {
      const pwd = prompt("请输入管理员密码解锁编辑功能：");
      if (pwd === ADMIN_PASSWORD) {
        setIsAdmin(true);
        localStorage.setItem('is_admin', 'true');
        setClickCount(0);
        alert("已切换至管理员模式，您的修改将同步至云端。");
      } else {
        setClickCount(0);
        alert("密码错误");
      }
    } else {
      setClickCount(newCount);
    }
  };

  const handleLogout = () => {
    setIsAdmin(false);
    localStorage.removeItem('is_admin');
  };

  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    let result = insights;
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();
      result = result.filter(i => 
        i.symbol.toLowerCase().includes(query) || 
        i.focusPoints.toLowerCase().includes(query) || 
        i.strategy.toLowerCase().includes(query)
      );
    }
    if (activeCategory !== '全部') {
      result = result.filter(i => i.category === activeCategory);
    }
    if (selectedMonth) {
      result = result.filter(i => {
        const date = new Date(i.updatedAt);
        return `${date.getFullYear()}年${date.getMonth() + 1}月` === selectedMonth;
      });
    }
    return result;
  }, [insights, activeCategory, selectedMonth, searchQuery]);

  const { activeItems, archivedItems } = useMemo(() => {
    return {
      activeItems: filteredInsights.filter(i => i.completionStatus === '进行中'),
      archivedItems: filteredInsights.filter(i => i.completionStatus !== '进行中')
    };
  }, [filteredInsights]);

  const groupedActiveInsights = useMemo(() => {
    const groups: { [label: string]: MarketInsight[] } = {};
    activeItems.forEach(insight => {
      let label = sortMode === 'timeline' 
        ? new Date(insight.updatedAt).toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' })
        : insight.category;
      if (!groups[label]) groups[label] = [];
      groups[label].push(insight);
    });
    const entries = Object.entries(groups);
    return sortMode === 'category' 
      ? entries.sort((a, b) => CATEGORIES.indexOf(a[0] as any) - CATEGORIES.indexOf(b[0] as any))
      : entries.sort((a, b) => b[1][0].updatedAt - a[1][0].updatedAt);
  }, [activeItems, sortMode]);

  const handleSaveInsight = async (data: Partial<MarketInsight>) => {
    if (!isAdmin) return;
    const targetId = editingInsight ? editingInsight.id : Math.random().toString(36).substr(2, 9);
    const updatedTimestamp = data.updatedAt || Date.now();

    const dbPayload = {
      id: targetId,
      symbol: data.symbol,
      category: data.category,
      status: data.status,
      focus_points: data.focusPoints,
      strategy: data.strategy,
      entry_level: data.entryLevel,
      updated_at: updatedTimestamp,
      completion_status: data.completionStatus || '进行中'
    };

    const { error } = await supabase
      .from('insights')
      .upsert(dbPayload);

    if (error) {
      alert("保存到数据库失败，请检查配置。");
      console.error(error);
    } else {
      fetchInsights(); // 刷新列表
      setShowForm(false);
      setEditingInsight(undefined);
    }
  };

  const handleDeleteInsight = async (id: string) => {
    if (!isAdmin) return;
    if (window.confirm('确定要从云端删除这条记录吗？')) {
      const { error } = await supabase
        .from('insights')
        .delete()
        .eq('id', id);

      if (error) {
        alert("删除失败");
      } else {
        fetchInsights();
      }
    }
  };

  const handleToggleCompletionStatus = async (id: string) => {
    if (!isAdmin) return;
    const item = insights.find(i => i.id === id);
    if (!item) return;

    const statuses: CompletionStatus[] = ['进行中', '已完成', '已失效'];
    const currentIndex = statuses.indexOf(item.completionStatus);
    const nextStatus = statuses[(currentIndex + 1) % statuses.length];

    const { error } = await supabase
      .from('insights')
      .update({ completion_status: nextStatus, updated_at: Date.now() })
      .eq('id', id);

    if (error) {
      alert("更新失败");
    } else {
      fetchInsights();
    }
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-amber-100">
      <header className="sticky top-0 z-[100] bg-white/80 backdrop-blur-xl border-b border-gray-100 px-8 h-[72px]">
        <div className="max-w-[1600px] mx-auto flex items-center justify-between h-full gap-8">
          <div className="flex items-center gap-3 shrink-0">
            <button 
              onClick={handleLogoClick}
              className={`w-8 h-8 rounded-lg flex items-center justify-center transition-all active:scale-90 ${isAdmin ? 'bg-amber-500 shadow-lg shadow-amber-200' : 'bg-[#12141c]'}`}
            >
              <LayoutGrid className="w-4 h-4 text-white" />
            </button>
            <div className="flex flex-col">
              <h1 className="text-lg font-black text-[#12141c] tracking-tighter hidden sm:block">市场周刊</h1>
            </div>
          </div>

          <div className="flex-grow flex items-center gap-4 max-w-3xl">
            <div className="relative group flex-grow">
              <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                <Search className={`w-4 h-4 transition-colors ${searchQuery ? 'text-gray-900' : 'text-gray-300'}`} />
              </div>
              <input
                type="text"
                className="w-full bg-gray-100/50 border border-transparent focus:bg-white focus:border-gray-200 py-2.5 pl-10 pr-10 rounded-2xl text-[13px] font-bold outline-none transition-all placeholder:text-gray-300"
                placeholder="搜索云端洞察记录..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
              {searchQuery && (
                <button onClick={() => setSearchQuery('')} className="absolute inset-y-0 right-0 pr-3 flex items-center text-gray-300 hover:text-gray-900 transition-colors">
                  <X className="w-4 h-4" />
                </button>
              )}
            </div>

            <nav className="hidden xl:flex items-center gap-1 bg-gray-100/50 p-1 rounded-2xl shrink-0">
              {CATEGORIES.map(cat => (
                <button
                  key={cat}
                  onClick={() => setActiveCategory(cat)}
                  className={`px-5 py-2 rounded-xl text-[13px] font-bold transition-all ${activeCategory === cat ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-400 hover:text-gray-900'}`}
                >
                  {cat}
                </button>
              ))}
            </nav>
          </div>

          <div className="flex items-center gap-4 shrink-0">
            <button onClick={fetchInsights} className={`p-2 text-gray-400 hover:text-gray-900 transition-all ${loading ? 'animate-spin' : ''}`}>
               <RefreshCw className="w-4 h-4" />
            </button>
            {isAdmin && (
              <div className="flex items-center gap-2">
                <button onClick={() => { setEditingInsight(undefined); setShowForm(true); }} className="bg-[#12141c] text-white flex items-center gap-2 px-6 py-2.5 rounded-full hover:scale-105 transition-all shadow-lg active:scale-95">
                  <Plus className="w-4 h-4" />
                  <span className="text-sm font-black hidden sm:inline">记录观点</span>
                </button>
                <button onClick={handleLogout} className="p-2 text-gray-300 hover:text-red-500 transition-colors">
                   <Lock className="w-4 h-4" />
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      <div className="max-w-[1600px] mx-auto px-8 py-12 w-full flex flex-col lg:flex-row gap-16">
        <aside className="lg:w-48 space-y-10 flex-shrink-0">
          <div className="sticky top-[100px]">
            <h3 className="text-[11px] font-black text-gray-300 uppercase tracking-[0.2em] mb-6">历史归档</h3>
            <div className="space-y-1">
              <button onClick={() => setSelectedMonth(null)} className={`w-full text-left px-4 py-3 rounded-xl text-[13px] font-bold transition-all flex items-center justify-between ${selectedMonth === null ? 'bg-[#12141c] text-white' : 'text-gray-400 hover:bg-gray-100'}`}>
                <span>全部记录</span>
                <span className="text-[10px] opacity-50">{insights.length}</span>
              </button>
              {timelineGroups.map(([month, count]) => (
                <button key={month} onClick={() => setSelectedMonth(month)} className={`w-full text-left px-4 py-3 rounded-xl text-[13px] font-bold transition-all flex items-center justify-between ${selectedMonth === month ? 'bg-[#12141c] text-white' : 'text-gray-400 hover:bg-gray-100'}`}>
                  <span>{month}</span>
                  <span className="text-[10px] opacity-50">{count}</span>
                </button>
              ))}
            </div>
          </div>
        </aside>

        <main className="flex-grow">
          {loading && insights.length === 0 ? (
             <div className="flex flex-col items-center justify-center py-32 opacity-20">
                <RefreshCw className="w-12 h-12 animate-spin mb-4" />
                <p className="font-black tracking-widest uppercase text-xs">正在连接同步云端数据...</p>
             </div>
          ) : (
            <>
              <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 mb-16">
                <h2 className="text-5xl font-black text-[#12141c] tracking-tighter leading-tight italic">
                  追踪行情，<br />每日洞察。
                </h2>
                <div className="flex bg-gray-100 p-1 rounded-xl border border-gray-200">
                  <button onClick={() => setSortMode('category')} className={`px-5 py-2 rounded-lg text-[12px] font-black transition-all ${sortMode === 'category' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-400'}`}>
                    <ListFilter className="w-3.5 h-3.5 mr-1 inline" /> 类别
                  </button>
                  <button onClick={() => setSortMode('timeline')} className={`px-5 py-2 rounded-lg text-[12px] font-black transition-all ${sortMode === 'timeline' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-400'}`}>
                    <CalendarDays className="w-3.5 h-3.5 mr-1 inline" /> 时间
                  </button>
                </div>
              </div>

              {activeItems.length > 0 ? (
                <div className="space-y-16">
                  {groupedActiveInsights.map(([groupLabel, groupItems]) => (
                    <section key={groupLabel}>
                      <div className="flex items-center gap-4 mb-10">
                        <span className="text-[12px] font-black tracking-widest uppercase bg-[#12141c] text-white px-4 py-1.5 rounded-full">{groupLabel}</span>
                        <div className="flex-grow h-[1px] bg-gray-100" />
                      </div>
                      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
                        {groupItems.map(insight => (
                          <MarketCard 
                            key={insight.id} 
                            insight={insight} 
                            onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}}
                            onDelete={isAdmin ? handleDeleteInsight : () => {}}
                            onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}}
                            isEditable={isAdmin}
                          />
                        ))}
                      </div>
                    </section>
                  ))}
                </div>
              ) : (
                <div className="text-center py-32 border-2 border-dashed border-gray-100 rounded-[3rem]">
                  <Plus className="w-10 h-10 text-gray-200 mx-auto mb-4" />
                  <h3 className="text-xl font-black text-gray-900">{searchQuery ? '没有找到相关记录' : '暂无进行中的记录'}</h3>
                </div>
              )}

              {archivedItems.length > 0 && (
                <div className="mt-40 pt-20 border-t border-gray-100">
                  <div className="flex items-center gap-4 mb-12">
                      <Archive className="w-6 h-6 text-gray-300" />
                      <h3 className="text-xl font-black text-[#12141c]">历史归档 <span className="text-gray-300 font-medium ml-2">{archivedItems.length}</span></h3>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8 grayscale opacity-60">
                    {archivedItems.map(insight => (
                      <MarketCard 
                        key={insight.id} 
                        insight={insight} 
                        onEdit={isAdmin ? (i) => { setEditingInsight(i); setShowForm(true); } : () => {}}
                        onDelete={isAdmin ? handleDeleteInsight : () => {}}
                        onToggleCompletion={isAdmin ? handleToggleCompletionStatus : () => {}}
                        isEditable={isAdmin}
                      />
                    ))}
                  </div>
                </div>
              )}
            </>
          )}
        </main>
      </div>

      {showForm && isAdmin && (
        <InsightForm initialData={editingInsight} onSave={handleSaveInsight} onCancel={() => { setShowForm(false); setEditingInsight(undefined); }} />
      )}
    </div>
  );
};

export default App;
